import csv
OUT="/home/claude/emst/docs/research/statecraft/statecraft_proficiency_anchors.csv"
H=["anchor_id","competency_ref","level","observable_behavior","evidence_of_performance","assessment_method","notes"]
L={1:"L1 Foundational",2:"L2 Intermediate",3:"L3 Advanced",4:"L4 Expert"}
A=[]
def add(c,ref,lvl,b,e,m,n=""):
    A.append([f"SC-A-{c}-{lvl}",ref,L[lvl],b,e,m,n])

r="SC-C01 Map decision authority and procedural pathway (v1 6.1.1|6.1.3|6.5.2)"
add("C01",r,1,"Given a defined project and reference lists, names the main federal, state, Tribal and local authorizations likely needed and the agency procedure (with version or date) that governs each, and flags what they are unsure of instead of guessing.","Completed authority checklist with at least 80% of key authorizations in a seeded case, and no confident errors.","Work sample: seeded case with answer key, scored by two raters.","Baseline knowledge. Years in v1 (0-2) are indicative only, not criteria.")
add("C01",r,2,"Independently produces a sequenced authority map and pathway plan for a multi-permit project: separates sequential from concurrent decisions, identifies the critical path and consultation triggers (ESA sec. 7, NHPA sec. 106, government-to-government), and names any delegated or assumed program holders.","Two or more real pathway plans adopted by project teams; a post-project audit finds few authorizations discovered after the plan was set.","Portfolio review against a rubric, plus a retrospective audit counting late-discovered authorizations.","Late-discovered authorizations are an objective, countable indicator.")
add("C01",r,3,"Resolves contested or novel authority questions (overlapping jurisdiction, uncertain delegation status, procedures that change mid-review) and re-plans the pathway without restarting the review; lays out options and risks for leadership.","Written analyses that counsel or leadership relied on; at least one instrument change absorbed without a restart.","Structured 'what-if' case interview (an instrument changes mid-review), plus 360 input from counsel and cooperating agencies.","Tests adaptation to the 2025-26 kind of churn.")
add("C01",r,4,"Designs pathway templates, screening logic (e.g., decision models) and procedure-version management that others in the organization use; negotiates agreements that settle recurring authority questions.","Adopted templates or models; fewer late authorizations measured across a program portfolio.","Artifact review and adoption metrics, judged by a peer panel.","Can be linked to CEQ standard decision_element and process_model entities.")

r="SC-C02 Build and maintain a defensible administrative record (v1 7.1.3|6.1.4|3.3.5)"
add("C02",r,1,"Files documents to the record index with correct dates, authors and provenance; records meeting outcomes and decisions using templates; labels AI-assisted content.","A QA sample of record entries meets the completeness and provenance checklist.","Record QA audit of a random sample of entries.","")
add("C02",r,2,"Builds a complete record for an EA-level decision: a decision memo explaining scope and effects boundaries, alternatives considered, responses to substantive comments and consultation outcomes; can certify the record by a deadline.","Record certified with no gaps found in QA; few supplementation requests.","Timed mock record-certification exercise, plus a checklist audit by a second reviewer.","Seven County deference rewards the reasoned explanation.")
add("C02",r,3,"Structures records for controversial decisions in anticipation of likely claims; writes the reasoned explanation linking evidence to choices; protects culturally sensitive information under terms agreed with the Tribe; supports counsel in litigation.","Records that survive challenge or need only limited remand; positive structured feedback from counsel.","Case review with counsel, plus a moot-court style oral defense of the decision rationale scored on a BARS.","Sensitive-information handling to be co-designed with TN (CARE).")
add("C02",r,4,"Sets record and AI-provenance standards for an organization, trains others, and leads post-litigation lessons-learned reviews.","Adopted record policy; audit results improve across units.","Artifact and outcome review by a peer panel.","Link to PermitTEC outcomes for benchmarking.")

r="SC-C03 Select, justify and document the level of review (v1 6.1.4|6.1.3)"
add("C03",r,1,"Applies a categorical-exclusion checklist to a routine action, cites the correct CE code, uses screening layers to spot possible extraordinary circumstances, and escalates uncertainty.","A seeded screening test is passed (correct CE, correct escalation); supervisor sign-off on a sample of real screens.","Graded screening test on seeded cases.","Procedure-specific content (CE codes) lives in the instrument layer; the behavior is durable.")
add("C03",r,2,"Makes and documents CE, EA or EIS determinations for typical actions, including adopting another agency's CE where allowed, a plan for page and time limits, and reasoned treatment of extraordinary circumstances.","Determinations accepted by the responsible official; low reversal or rework rate.","Panel file review of a sample of determinations with inter-rater comparison.","Inter-rater agreement doubles as a reliability check for IO.")
add("C03",r,3,"Handles borderline cases (stacking vs. segmentation, programmatic tiering, emergencies, Sec. 112 fee requests) and advises sponsors and responsible officials on trade-offs.","Written advice memos; borderline determinations that hold up on review.","Structured case interview, plus a decision audit.","")
add("C03",r,4,"Writes or revises agency CE categories, screening criteria and guidance, and backs new CEs with evidence of no significant effect.","Adopted CE categories or screening models; external review comments resolved.","Artifact review, plus external peer review.","")

r="SC-C05 Supervise AI-assisted drafting and comment analysis (v1 6.4.4|7.2.1|7.1.3)"
add("C05",r,1,"Uses only approved AI tools within policy; checks cited facts and sources in AI drafts; flags uncertainty; labels AI-assisted text.","Verification log for each AI-assisted draft; planted errors caught in a test.","Seeded-error detection test (an AI draft with planted factual, citation and legal errors).","Shared boundary with DC 7.2.1; this anchor stresses legal consequence.")
add("C05",r,2,"Designs and runs a sampling check of AI comment groupings (estimating how many substantive comments were missed or merged), finds unique substantive comments, and confirms every substantive comment has a reasoned response.","Validation log with sample statistics; a complete comment-response matrix.","Work sample on a test docket with known unique comments, scored on detection rate and response adequacy.","Critical if a unique-comment standing rule (SPEED) is enacted.")
add("C05",r,3,"Writes the project AI-use plan (which tasks, which checks, who signs off), consistent with the agency's AI governance, and defends the methods to counsel and reviewers.","Approved AI-use plan; no record defects traced to AI.","Plan review against a rubric, plus a challenge interview.","")
add("C05",r,4,"Sets organizational AI-use standards and evaluation benchmarks for permitting tasks and leads incident reviews when AI errors reach the record.","Adopted standards; benchmark results; incident reviews completed.","Artifact review by a peer panel.","Benchmarks can borrow task designs from DraftNEPABench and NEPABench.")

r="SC-C06 Design proportionate public engagement (v1 5.2.1|5.2.2|5.2.3|6.4.4)"
add("C06",r,1,"For an action, identifies affected parties and which participation steps are legally required and which are discretionary; logs contacts; runs logistics for meetings and comment periods.","Accurate required-vs-discretionary checklist on a seeded case; complete contact log.","Checklist test, plus supervisor observation.","")
add("C06",r,2,"Writes an engagement plan sized to legitimacy and litigation risk; picks methods suited to the parties; closes the loop with a 'what we heard and what changed' record.","Approved plan and closing report; participant feedback.","Rubric review of plan and report, plus a participant survey and observation of one session.","Keeps government-to-government consultation as a separate track (SC-C13).")
add("C06",r,3,"Designs engagement for contested decisions with several publics, including overburdened communities and Tribes (on a separate track); times it to the decision; adapts when conflict escalates.","The decision record shows engagement changed the outcome or the mitigation; less late-stage opposition.","Case portfolio review, plus 360 input from community partners.","")
add("C06",r,4,"Sets organizational policy on when to go beyond legal minimums, mentors others, and evaluates engagement outcomes across a portfolio.","Adopted policy; evaluation report.","Artifact and outcome review.","")

r="SC-C07 Negotiate permit conditions, mitigation and agreements (v1 5.2.4|6.1.3|6.6.2)"
add("C07",r,1,"Prepares a negotiation brief (own interests, the counterpart's likely interests, alternatives to agreement, issue list, authority limits) and supports a lead negotiator.","Graded preparation brief.","Brief scored in a standardized simulation.","Teachability: experimental negotiation-training literature (SC-050, SC-052; unverified this session).")
add("C07",r,2,"Leads routine negotiations over permit conditions or mitigation, generates options, and reaches agreements that are within authority and can be implemented.","Agreements reached; counterpart ratings of fairness and clarity.","Standardized role-play scored on a BARS by trained raters, plus counterpart feedback.","Simulations allow reliable, repeatable assessment.")
add("C07",r,3,"Leads high-stakes multi-party negotiations (HCPs, settlements, multi-agency agreements); manages coalitions and breaks deadlocks.","A portfolio of concluded agreements; 360 from counterparts.","Complex multi-party simulation, plus portfolio review.","")
add("C07",r,4,"Sets organizational negotiation strategy, coaches others, and is sought out as negotiator or neutral.","Peer nominations; outcomes of coached negotiations.","Peer panel and portfolio review.","")

r="SC-C08 Design and administer cross-jurisdictional stewardship agreements (v1 6.5.3|6.5.2|5.2.5)"
add("C08",r,1,"Prepares agreement documents from templates, tracks deliverables, invoices and revenue ledgers, and spots discrepancies.","Clean document QA and audit sample.","Document QA, plus a ledger reconciliation exercise.","Examples include GNA project agreements and co-stewardship MOUs.")
add("C08",r,2,"Scopes and drafts project agreements within legal authority (roles, reporting, revenue retention and reinvestment) and manages the partner relationship day to day.","Executed agreements without legal-review rework; partner feedback; clean audit findings.","Work-sample review by an agreements officer, plus partner feedback.","")
add("C08",r,3,"Designs master agreements and multi-partner programs (state, county, Tribe, NGO), works within limits on delegating inherent government functions, resolves disputes, and keeps agreements going through staff turnover.","Program portfolio; legal review findings; partner 360.","Portfolio review, plus a structured interview on a dispute case.","Tribal agreements co-assessed with TN.")
add("C08",r,4,"Shapes enabling law and policy (e.g., state GNA statutes such as Colorado HB26-1205) and statewide program design, and evaluates program outcomes.","Adopted policy or legislation; program evaluation.","Artifact and outcome review.","")

r="SC-C09 Coordinate lead, cooperating and participating agencies to a shared schedule (v1 6.5.2|6.5.3)"
add("C09",r,1,"Keeps schedules, milestone trackers and dashboard entries accurate and prepares interagency meeting materials.","Data-accuracy audit passed.","Audit of tracker and dashboard entries against source documents.","FAST-41 dashboard data is public and auditable.")
add("C09",r,2,"Runs interagency coordination for a project: agrees roles, keeps a joint schedule, resolves routine conflicts and escalates the rest.","Milestones met or deviations justified; cooperating-agency feedback.","Milestone records review, plus 360 from cooperating agencies.","")
add("C09",r,3,"Leads coordination on complex or covered projects, negotiates jurisdiction-by-law disputes, and documents cooperating-agency decisions.","Case outcomes; written justifications; 360.","Case review, plus structured interview.","")
add("C09",r,4,"Designs standing interagency agreements and coordination structures and sets organizational policy.","Adopted agreements and structures.","Artifact review and adoption evidence.","")

r="SC-C10 Formulate, justify and execute public budgets (v1 3.1.2|3.4.2|6.4.5)"
add("C10",r,1,"Tracks obligations and spending accurately against appropriations, agreements and fee accounts, and applies basic rules on purpose and period of availability.","Reconciliation test passed; clean audit sample.","Reconciliation exercise, plus audit.","UK standard 2.3 Finance Level 1 is a comparable benchmark.")
add("C10",r,2,"Prepares a program budget request and justification linking funds to outcomes, plans for continuing-resolution scenarios, and manages fees or retained revenue by the rules.","Budget justification accepted by the budget office; contingency plan in place.","Work sample (budget justification) scored by a budget officer.","")
add("C10",r,3,"Leads budget formulation for a multi-program unit, briefs appropriators, boards or councils, and designs cost-recovery or fee structures within law.","Portfolio of submissions; observed briefing.","Portfolio review, plus observed or simulated appropriations briefing.","")
add("C10",r,4,"Shapes funding strategy across organizations and secures durable funding mechanisms.","Mechanisms enacted or adopted.","Outcome review by a peer panel.","Federal FY2026-27 appropriations status not verified this session.")

r="SC-C11 Assess durability and reversal risk; time actions to windows (v1 6.4.1|6.4.2|6.4.5)"
add("C11",r,1,"Classifies an instrument by type (statute, regulation, guidance, handbook, agreement, permit, case law) and explains how each can be changed and by whom.","Knowledge test passed.","Short-answer knowledge test.","The behavioral core of what is usually called 'political savvy'.")
add("C11",r,2,"Assesses the reversal risk of a program's key instruments, proposes contingencies, and identifies coming decision windows (rule deadlines, budget cycles, elections, litigation milestones).","Risk memo scored against a rubric.","Written risk memo, plus a situational judgment test.","SJT validity needs IO evidence.")
add("C11",r,3,"Advises leadership on choosing and timing instruments for durability, and anticipates litigation and changes of administration.","A prediction log reviewed for calibration over time; leadership feedback.","Structured interview, plus calibration review of recorded forecasts.","A forecast log makes judgment observable over time.")
add("C11",r,4,"Designs governance arrangements that survive transitions and is recognized across organizations for this judgment.","Case evidence of arrangements that lasted.","Peer panel review.","")

with open(OUT,"w",newline="",encoding="utf-8") as f:
    w=csv.writer(f); w.writerow(H)
    for x in A:
        assert len(x)==len(H)
        w.writerow(x)
print(len(A))
